<script setup lang="ts">
import {ref,onMounted} from 'vue';import {pmsApi} from './api';
const props=defineProps<{kind:string;csrf?:string}>();const form=ref<any>(null),error=ref(''),message=ref(''),busy=ref(false),files=ref<Record<string,File>>({});
const testEmail=ref(''),showSecret=ref(false),previews=ref<Record<string,string>>({});function pick(field:string,event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;files.value[field]=file;if(previews.value[field])URL.revokeObjectURL(previews.value[field]);previews.value[field]=URL.createObjectURL(file);}const brandGroups=[{title:'Workspace identity',description:'Logos used inside the application.',icon:'layout-sidebar',fields:['sidebar_logo','sidebar_logo_text','sidebar_logo_text_dark','favicon']},{title:'Sign-in experience',description:'Branding presented before users log in.',icon:'login',fields:['login_logo','login_logo_dark','login_cover','login_cover_dark']}];const brandLabels:Record<string,string>={sidebar_logo:'Sidebar icon',sidebar_logo_text:'Sidebar wordmark - Light',sidebar_logo_text_dark:'Sidebar wordmark - Dark',favicon:'Browser favicon',login_logo:'Login logo - Light',login_logo_dark:'Login logo - Dark',login_cover:'Login cover - Light',login_cover_dark:'Login cover - Dark'};async function test(){busy.value=true;error.value='';try{const d=await pmsApi('settings/'+props.kind+'/test',props.csrf||'','POST',props.kind==='mail'?{test_email:testEmail.value}:{});message.value=d.message;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
const brandingFields=['sidebar_logo','sidebar_logo_text','sidebar_logo_text_dark','login_logo','login_logo_dark','login_cover','login_cover_dark','favicon'];
async function load(){try{const d=await pmsApi('settings/'+props.kind);form.value=d.data.settings||d.data.branding;error.value='';}catch(e){error.value=(e as Error).message;}}
async function save(){busy.value=true;error.value='';message.value='';try{let body:any={...form.value};if(props.kind==='branding'){body=new FormData();Object.entries(files.value).forEach(([k,v])=>body.append(k,v));}const r=await fetch('/pms/api/settings/'+props.kind,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf||'',...(body instanceof FormData?{}:{'Content-Type':'application/json'})},body:body instanceof FormData?body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message);message.value=d.message;await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(load);
</script>
<template>
<p v-if="error" class="notice admin-error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p><p v-if="!form&&!error" role="status">Loading settings...</p>
<div v-if="form&&kind==='branding'" class="branding-page"><div class="branding-hero"><div><span class="branding-eyebrow">Workspace appearance</span><h2>Branding settings</h2><p>Keep your workspace and sign-in experience consistent across every screen.</p></div><div class="branding-security"><i aria-hidden="true" class="ti ti-shield-lock"></i><span><strong>Admin controlled</strong><small>Permission-protected settings</small></span></div></div><form class="branding-form" @submit.prevent="save"><div class="branding-grid"><section v-for="group in brandGroups" :key="group.title" class="branding-panel"><header class="branding-panel-header"><span class="branding-panel-icon"><i aria-hidden="true" class="ti" :class="'ti-'+group.icon"></i></span><div><h4>{{group.title}}</h4><p>{{group.description}}</p></div></header><div v-for="field in group.fields" :key="field" class="branding-asset"><div class="branding-asset-preview" :class="field.includes('cover')?'is-cover':field==='sidebar_logo'||field==='favicon'?'is-square':'is-wide'"><img :src="previews[field]||(form[field]?'/storage/'+form[field]:'/pms-assets/assets/img/'+(field.includes('cover')?'illustrations/auth-login-illustration-light.png':field==='sidebar_logo'||field==='favicon'?'sm-logo.png':'logo.png'))" :alt="brandLabels[field]"></div><div class="branding-asset-info"><h5>{{brandLabels[field]}}</h5><p>{{field.includes('dark')?'Optional image for the dark theme':'Image used in the workspace'}}</p><div class="branding-upload"><label class="branding-upload-label"><i aria-hidden="true" class="ti ti-upload"></i>Choose file<input class="branding-file" type="file" accept="image/*" @change="pick(field,$event)"></label><span class="branding-file-name">{{files[field]?.name||'No file selected'}}</span></div><small class="branding-hint">{{field.includes('cover')?'Landscape PNG/JPG/WebP - Max 5 MB':field==='favicon'?'PNG/ICO/WebP - Max 1 MB':field.includes('login')?'Transparent PNG/WebP - Max 3 MB':'PNG/WebP - Max 2 MB'}}</small></div></div></section></div><div class="branding-savebar"><div><i aria-hidden="true" class="ti ti-info-circle"></i><span>Only selected files will change. Empty fields keep their current image.</span></div><button class="button primary" :disabled="busy"><i aria-hidden="true" class="ti ti-device-floppy"></i>{{busy?'Saving...':'Save changes'}}</button></div></form></div>
<div v-else-if="form&&kind==='mail'" class="mail-settings-page"><div class="mail-settings-hero"><div><span>Email delivery</span><h2>SMTP settings</h2><p>Configure the email server used for task invitations and application notifications.</p></div><div class="mail-security"><i aria-hidden="true" class="ti ti-lock"></i><div><strong>Encrypted credentials</strong><small>The SMTP password is encrypted at rest.</small></div></div></div><div class="mail-settings-grid"><form class="mail-panel" @submit.prevent="save"><div class="mail-panel-heading"><i aria-hidden="true" class="ti ti-server"></i><div><h4>Mail server</h4><p>Credentials provided by your email hosting provider.</p></div></div><div class="pms-settings-fields"><label class="mail-switch"><span><strong>Notification emails</strong><small>Assignment and task activity emails.</small></span><input type="checkbox" v-model="form.notification_emails_enabled"></label><label class="mail-switch"><span><strong>Invitation emails</strong><small>Send secure invitation links by email.</small></span><input type="checkbox" v-model="form.invitation_emails_enabled"></label><label>Daily sending limit<input type="number" v-model.number="form.daily_limit" min="0" required><small class="muted">Use 0 for no application limit.</small></label><label>Warning threshold<input type="number" v-model.number="form.warning_threshold" min="0" required></label><label>SMTP host<input v-model="form.host" placeholder="smtp.example.com"></label><label>Port<input type="number" v-model.number="form.port" min="1" max="65535" required></label><label>Encryption<select v-model="form.scheme"><option value="smtp">TLS / STARTTLS</option><option value="smtps">SSL</option></select></label><label>Username<input v-model="form.username" autocomplete="off" placeholder="mailbox@example.com"></label><label class="full-width">Password<div class="input-group"><input :type="showSecret?'text':'password'" v-model="form.password" autocomplete="new-password" placeholder="Leave blank to keep saved password"><button type="button" class="button" aria-label="Toggle password visibility" @click="showSecret=!showSecret"><i aria-hidden="true" class="ti ti-eye"></i></button></div><small class="muted">For security, the saved password is never displayed.</small></label></div><div class="mail-panel-heading mt-4"><i aria-hidden="true" class="ti ti-send"></i><div><h4>Sender identity</h4><p>The name and address recipients see in their inbox.</p></div></div><div class="pms-settings-fields"><label>From address<input type="email" v-model="form.from_address"></label><label>From name<input v-model="form.from_name"></label></div><div class="editor-actions"><button class="button primary" :disabled="busy"><i aria-hidden="true" class="ti ti-device-floppy"></i>{{busy?'Saving...':'Save email settings'}}</button></div></form><aside class="mail-panel mail-test-panel"><div class="mail-panel-heading"><i aria-hidden="true" class="ti ti-mail"></i><div><h4>Test delivery</h4><p>Send a real message using the saved configuration.</p></div></div><div class="mail-status" :class="{'is-enabled':form.host}"><span></span><div><strong>{{form.host?'SMTP configured':'SMTP setup required'}}</strong><small>{{form.host?form.host+':'+form.port:'Complete and save the mail server fields.'}}</small></div></div><form class="pms-settings-fields" @submit.prevent="test"><label class="full-width">Send test to<input type="email" v-model="testEmail" required></label><button class="button" :disabled="busy||!form.host"><i aria-hidden="true" class="ti ti-send"></i>Send test email</button></form><div class="mail-help"><i aria-hidden="true" class="ti ti-info-circle"></i><p><strong>Common settings</strong><br>TLS normally uses port 587. SSL normally uses port 465.</p></div></aside></div></div>
<div v-else-if="form" class="realtime-settings-page"><div class="realtime-hero"><div><span>Live workspace</span><h2>Realtime / Pusher settings</h2><p>Manage instant notifications and live board updates without server access.</p></div><div class="realtime-security"><i aria-hidden="true" class="ti ti-shield-lock"></i><div><strong>Encrypted secret</strong><small>The App Secret is encrypted and never returned to the browser.</small></div></div></div><div class="realtime-grid"><form class="realtime-panel" @submit.prevent="save"><div class="realtime-panel-heading"><i aria-hidden="true" class="ti ti-broadcast"></i><div><h4>Pusher Channels</h4><p>Blank credentials use the existing Laravel Reverb server.</p></div></div><label class="realtime-switch mb-4"><span><strong>Enable realtime updates</strong><small>Deliver notifications and board changes instantly.</small></span><input type="checkbox" v-model="form.enabled"></label><div class="pms-settings-fields"><label>App ID<input v-model="form.app_id" autocomplete="off" placeholder="Uses server settings when blank"></label><label>App Key<input v-model="form.app_key" autocomplete="off"></label><label>Cluster<input v-model="form.cluster" placeholder="For example: ap2"></label><label>App Secret<div class="input-group"><input :type="showSecret?'text':'password'" v-model="form.app_secret" autocomplete="new-password" placeholder="Leave blank to keep saved secret"><button type="button" class="button" aria-label="Toggle secret visibility" @click="showSecret=!showSecret"><i aria-hidden="true" class="ti ti-eye"></i></button></div><small class="muted">The saved value is never displayed.</small></label></div><div class="editor-actions"><button class="button primary" :disabled="busy"><i aria-hidden="true" class="ti ti-device-floppy"></i>{{busy?'Saving...':'Save realtime settings'}}</button></div></form><aside class="realtime-panel"><div class="realtime-panel-heading"><i aria-hidden="true" class="ti ti-plug-connected"></i><div><h4>Connection test</h4><p>Send a private live event to your account.</p></div></div><div class="realtime-status" :class="{'is-enabled':form.enabled}"><span></span><div><strong>{{form.enabled?'Realtime enabled':'Realtime disabled'}}</strong><small>{{form.cluster?'Cluster: '+form.cluster:'Server connection settings'}}</small></div></div><form @submit.prevent="test"><button class="button" :disabled="busy||!form.enabled"><i aria-hidden="true" class="ti ti-bolt"></i>Send live test</button></form><div class="realtime-help"><i aria-hidden="true" class="ti ti-info-circle"></i><p>After changing credentials, refresh open browser tabs. Database notifications remain available after refresh.</p></div></aside></div></div>
</template>